import axioInstance  from '@/api/axiosInstance';
import { useEffect } from 'react'


export default function Resource(){

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await axioInstance.get("/api/content");
                setData(response.data);
            } catch (error) {
                setError(error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    return (
        <div>
            <h1>Resource Page</h1>
        </div>
    )
}